        "financial_resources_scale": "2",
        "fcommunication_description": "Poor communication, such as accusatory language and long aggressive emails that are ineffective in building a good co-parenting relationship. Each parent constantly accuses the other of various issues. ",
        "children_insurance_provider": "Tricare ",
        "family_needs_assistance_txt": "",
        "residential_stability_scale": "2",
        "caregiver_insurance_provider": "Tricare",
        "fappropriateness_description": "",
